import { createHmac } from "node:crypto";
export default function verify({ body, secret }) {
  if (typeof secret !== "string" || !secret) throw Error("Configure the shared signing secret");
  const raw = String(body?.raw || ""),
    signature = String(body?.signature || "")
      .trim()
      .toLowerCase(),
    contentType = String(body?.contentType || "").toLowerCase();
  let accepted = false,
    id = null;
  try {
    if (!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(raw))
      throw Error("Invalid encoding");
    const bytes = Buffer.from(raw, "base64");
    if (bytes.toString("base64") !== raw) throw Error("Invalid encoding");
    const payload = JSON.parse(bytes.toString("utf8")),
      expected = createHmac("sha256", secret).update(bytes).digest("hex"),
      match = /^sha256=([a-f0-9]{64})$/.exec(signature);
    let diff = 0;
    if (match) for (let i = 0; i < 64; i++) diff |= expected.charCodeAt(i) ^ match[1].charCodeAt(i);
    const valid = !!match && diff === 0,
      now = Math.floor(Date.now() / 1000),
      fresh =
        Number.isInteger(payload.sent_at) &&
        payload.sent_at >= now - 300 &&
        payload.sent_at <= now + 60;
    id =
      typeof payload.event_id === "string" && /^evt_[A-Za-z0-9-]{8,64}$/.test(payload.event_id)
        ? payload.event_id
        : null;
    accepted = valid && fresh && !!id && contentType.startsWith("application/json");
  } catch {}
  return {
    result: accepted
      ? {
          ok: true,
          status: "accepted",
          authenticated: true,
          event_id: id,
          replay_window_seconds: 300,
        }
      : { ok: false, status: "rejected", reason: "invalid_or_stale_signature" },
  };
}
